  fun minutesAgo(n: Any): String = t("$n دقیقه پیش", "$n ${pl(n, "minute", "minutes")} ago", "$n ${pl(n, "دقیقه", "دقیقې")} مخکې")
  fun hoursAgo(n: Any): String = t("$n ساعت پیش", "$n ${pl(n, "hour", "hours")} ago", "$n ساعته مخکې")
  fun daysAgo(n: Any): String = t("$n روز پیش", "$n ${pl(n, "day", "days")} ago", "$n ${pl(n, "ورځ", "ورځې")} مخکې")
}
